-- ======== from 09 (provider_price_for only) ========
-- Test project only: quick-request routing + price.
--   1) offers go first to providers whose coverage area matches the booking area;
--      if nobody matches, or after the 10-minute escalation, to providers within 60 km of the client.
--   2) the booking price is set from the accepting provider's own price (provider_services.custom_price,
--      else the admin minimum for the provider's grade); the offer shows that price before accepting.

-- price a provider would charge for a booking's service
create or replace function public.provider_price_for(p_provider_id uuid, p_service_type text, p_sub_option text)
 returns numeric
 language sql
 stable
 security definer
 set search_path to 'public'
as $$
  with prov as (select grade from public.providers where id = p_provider_id),
  match as (
    select ss.*, ps.custom_price
    from public.sub_services ss
    left join public.provider_services ps
      on ps.sub_service_id = ss.id and ps.provider_id = p_provider_id and ps.is_active = true
    where ss.service_name = p_service_type
      and p_sub_option is not null
      -- doctor quick requests store "<grade> <specialty>" in sub_option
      and (ss.name = p_sub_option or p_sub_option like '% ' || ss.name)
    order by (ps.custom_price is not null) desc, length(ss.name) desc
    limit 1
  )
  select coalesce(
    m.custom_price,
    case when (select grade from prov) = 'استشاري'
         then coalesce(m.price_min_consultant, m.price_min)
         else coalesce(m.price_min_specialist, m.price_min) end
  )
  from match m;
$$;

-- ======== from 10 (norm_ar only) ========
-- Test project only: smarter area matching for quick-request routing (run AFTER 09_quick_request_routing.sql).
-- Arabic names are normalized before comparing (hamza/alef forms, ى/ي, ة/ه, tashkeel, the "ال" prefix, punctuation),
-- and a provider who lists a whole governorate (e.g. "الجيزة") matches every area inside it.

create or replace function public.norm_ar(p text)
 returns text
 language sql
 immutable
as $$
  select trim(regexp_replace(
    regexp_replace(
      regexp_replace(
        regexp_replace(
        translate(lower(coalesce(p, '')), 'أإآٱىةؤئ', 'اااايهوي'),
        '[\u064B-\u0652\u0640]', '', 'g'),                 -- tashkeel + tatweel
      '[^a-z0-9\u0621-\u064A ]', ' ', 'g'),                 -- punctuation -> space
    '(^| )ال', '\1', 'g')                                    -- leading "ال" of every word
  , '\s+', ' ', 'g'))
$$;

-- ======== from 11 (push helpers only; original notify_* triggers are NOT replaced; pg_net already exists on the original) ========
-- Test project only: free push notifications straight from the database to Expo's push service (pg_net),
-- no Edge Function and no emails. Replaces the no-op triggers from 02_functions.sql.
--   * a new offer / direct booking  -> push to the provider
--   * booking confirmed (with provider name + price), on the way, completed, cancelled -> push to the client
-- Android push also needs an FCM V1 key uploaded in Expo for each app package (done once, outside the database).


create or replace function public.send_expo_push(p_tokens text[], p_title text, p_body text, p_data jsonb)
 returns void
 language plpgsql
 security definer
 set search_path to 'public', 'extensions'
as $function$
begin
  if p_tokens is null or coalesce(array_length(p_tokens, 1), 0) = 0 then
    return;
  end if;
  perform net.http_post(
    url := 'https://exp.host/--/api/v2/push/send',
    headers := '{"Content-Type": "application/json"}'::jsonb,
    body := (
      select jsonb_agg(jsonb_build_object(
        'to', t, 'title', p_title, 'body', p_body, 'data', p_data, 'sound', 'default', 'priority', 'high'))
      from unnest(p_tokens) as t
    )
  );
exception when others then
  -- a failed push must never block the booking itself
  null;
end;
$function$;

revoke all on function public.send_expo_push(text[], text, text, jsonb) from public, anon, authenticated;

create or replace function public.provider_push_tokens(p_provider_id uuid)
 returns text[]
 language sql
 stable
 security definer
 set search_path to 'public'
as $$
  select coalesce(array_agg(expo_token), '{}') from (
    select expo_token from public.push_tokens
    where owner_type = 'provider' and provider_id = p_provider_id
    order by updated_at desc limit 2) s;
$$;

create or replace function public.client_push_tokens(p_phone text)
 returns text[]
 language sql
 stable
 security definer
 set search_path to 'public'
as $$
  select coalesce(array_agg(expo_token), '{}') from (
    select expo_token from public.push_tokens
    where owner_type = 'client' and phone = p_phone
    order by updated_at desc limit 3) s;
$$;

revoke all on function public.provider_push_tokens(uuid) from public, anon, authenticated;
revoke all on function public.client_push_tokens(text) from public, anon, authenticated;

