update public.coverage_areas a set name_en = g.name_en
from public.governorates g where a.name = g.name and a.name_en is null and g.name_en is not null;

-- ======== from 24_admin_set_appointment.sql ========
-- Test project only. Admin can set / change a consultation's appointment to ANY time (no period limit).
-- The new time is confirmed directly (both sides are notified); the doctor/patient proposal flow keeps its own rules.
create or replace function public.admin_set_appointment(p_id uuid, p_at timestamptz)
 returns text language plpgsql security definer set search_path to 'public'
as $$
declare c public.consultations;
begin
  if not public.is_admin() then return 'forbidden'; end if;
  select * into c from public.consultations where id = p_id for update;
  if c.id is null then return 'forbidden'; end if;
  if c.pay_status <> 'paid' or c.state <> 'wait' then return 'locked'; end if;
  if p_at < now() - interval '1 minute' then return 'past'; end if;
  update public.consultations
     set appt_at = p_at, prop_at = p_at, prop_status = 'ok', flags = '{}'::jsonb, admin_contacted_at = null
   where id = p_id;
  perform public.consult_push(p_id, 'c', 'تم تحديد موعد استشارتك', 'حددت الإدارة موعدًا جديدًا — افتح الحجز');
  perform public.consult_push(p_id, 'd', 'موعد استشارة جديد', 'حددت الإدارة موعدًا لاستشارة — افتح الحجز');
  return 'ok';
end; $$;
revoke all on function public.admin_set_appointment(uuid, timestamptz) from public, anon;
grant execute on function public.admin_set_appointment(uuid, timestamptz) to authenticated;

-- ======== from 25_appointment_time_reminders.sql ========
-- Test project only. Two more reminders around the appointment (consultations_tick):
--   * 'at'  : the moment the appointment time arrives  -> "حان موعد استشارتك" (doctor + client)
--   * 'l5'  : 5 minutes after the time and the session still not started -> reminder again
-- (the existing r30, r10 and the 15-minute "late" notice stay as they are)
create or replace function public.consultations_tick()
 returns void language plpgsql security definer set search_path to 'public', 'extensions'
as $$
declare c public.consultations; v_end timestamptz;
begin
  for c in select * from public.consultations where pay_status = 'paid' and state in ('wait', 'live') loop
    if c.state = 'wait' and c.prop_status = 'ok' then
      if not (c.flags ? 'r30') and now() >= c.appt_at - interval '30 minutes' and now() < c.appt_at then
        perform public.consult_push(c.id, 'd', 'استشارة بعد 30 دقيقة', 'استعد لموعد الاستشارة');
        perform public.consult_push(c.id, 'c', 'استشارتك بعد 30 دقيقة', 'استعد لموعد الاستشارة');
        update public.consultations set flags = flags || '{"r30": true}' where id = c.id;
      end if;
      if not (c.flags ? 'r10') and now() >= c.appt_at - interval '10 minutes' and now() < c.appt_at + interval '15 minutes' then
        perform public.consult_push(c.id, 'd', 'استشارة بعد 10 دقائق', 'تقدر تبدأ الجلسة الآن');
        perform public.consult_push(c.id, 'c', 'استشارتك بعد 10 دقائق', 'استعد، الطبيب هيبدأ قريبًا');
        update public.consultations set flags = flags || '{"r10": true}' where id = c.id;
      end if;
      -- the appointment time has arrived
      if not (c.flags ? 'at') and now() >= c.appt_at and now() < c.appt_at + interval '15 minutes' then
        perform public.consult_push(c.id, 'd', 'حان موعد الاستشارة', 'اضغط لبدء الجلسة الآن');
        perform public.consult_push(c.id, 'c', 'حان موعد استشارتك', 'الطبيب هيبدأ الجلسة، ابقَ جاهزًا');
        update public.consultations set flags = flags || '{"at": true}' where id = c.id;
      end if;
      -- still not started 5 minutes later
      if not (c.flags ? 'l5') and now() >= c.appt_at + interval '5 minutes' and now() < c.appt_at + interval '15 minutes' then
        perform public.consult_push(c.id, 'd', 'لم تبدأ الاستشارة بعد', 'المريض بانتظارك — ابدأ الجلسة الآن');
        perform public.consult_push(c.id, 'c', 'الاستشارة لم تبدأ بعد', 'الطبيب هيبدأ قريبًا، ابقَ جاهزًا');
        update public.consultations set flags = flags || '{"l5": true}' where id = c.id;
      end if;
      if not (c.flags ? 'ltd') and now() >= c.appt_at + interval '15 minutes' then
        perform public.consult_push(c.id, 'd', 'تأخرت عن موعد الاستشارة', 'ابدأها الآن');
        perform public.consult_push(c.id, 'c', 'تأخر الطبيب قليلًا', 'الإدارة تتابع');
        update public.consultations set flags = flags || '{"ltd": true}' where id = c.id;
      end if;
    elsif c.state = 'live' then
      v_end := public.consult_end_at(c);
      if now() >= v_end then
        update public.consultations set state = 'ended', ended_at = v_end where id = c.id;
        perform public.consult_push(c.id, 'd', 'انتهت الاستشارة', 'اكتب ملخص الاستشارة');
        perform public.consult_push(c.id, 'c', 'انتهت الاستشارة', 'بانتظار ملخص الطبيب');
      else
        if c.client_in_at is null and not (c.flags ? 'nudge') and now() >= c.started_at + interval '5 minutes' then
          perform public.consult_push(c.id, 'c', 'الطبيب بانتظارك', 'بدأت استشارتك — اضغط للدخول');
          update public.consultations set flags = flags || '{"nudge": true}' where id = c.id;
        end if;
        if not (c.flags ? 'e5') and v_end - now() <= interval '5 minutes' and c.duration_min + c.extra_min > 5 then
          perform public.consult_push(c.id, 'd', 'متبقي 5 دقائق', 'على انتهاء الاستشارة');
          perform public.consult_push(c.id, 'c', 'متبقي 5 دقائق', 'على انتهاء الاستشارة');
          update public.consultations set flags = flags || '{"e5": true}' where id = c.id;
        end if;
      end if;
    end if;
  end loop;
end; $$;
revoke all on function public.consultations_tick() from public, anon, authenticated;

-- ======== from 26 (cron removed -> 03) ========
-- Test project only. After a consultation ends, remind the doctor to write the summary if it is still missing:
--   10 minutes after the end and again after 1 hour (one push each). Runs every minute with pg_cron.
create or replace function public.consultations_summary_tick()
 returns void language plpgsql security definer set search_path to 'public', 'extensions'
as $$
declare c public.consultations;
begin
  for c in select * from public.consultations
            where state = 'ended' and not no_show and sum_at is null and pay_status = 'paid'
              and ended_at > now() - interval '3 days' loop
    if not (c.flags ? 'sm10') and now() >= c.ended_at + interval '10 minutes' then
      perform public.consult_push(c.id, 'd', 'ملخص الاستشارة مطلوب', 'اكتب ملخص الاستشارة ليصل للمريض');
      update public.consultations set flags = flags || '{"sm10": true}' where id = c.id;
    elsif c.flags ? 'sm10' and not (c.flags ? 'sm60') and now() >= c.ended_at + interval '1 hour' then
      perform public.consult_push(c.id, 'd', 'تذكير: ملخص الاستشارة', 'المريض بانتظار ملخص استشارتك');
      update public.consultations set flags = flags || '{"sm60": true}' where id = c.id;
    end if;
  end loop;
end; $$;
revoke all on function public.consultations_summary_tick() from public, anon, authenticated;

-- ======== from 27_ratings_to_reviews_and_summary_admin.sql ========
-- Test project only.
--  1) Approving a consultation rating publishes it as a review (doctor page + average rating). No duplicates.
--  2) The admin list also returns the doctor's summary.

alter table public.reviews add column if not exists consultation_id uuid;
create unique index if not exists reviews_consultation_uniq on public.reviews (consultation_id) where consultation_id is not null;

create or replace function public.admin_approve_rating(p_id uuid)
 returns text language plpgsql security definer set search_path to 'public'
as $$
declare c public.consultations;
begin
  if not public.is_admin() then return 'forbidden'; end if;
  update public.consultations set rating_ok = true where id = p_id and rating is not null returning * into c;
  if c.id is null then return 'locked'; end if;
  insert into public.reviews (client_name, service_type, rating, text, is_approved, provider_id, consultation_id)
  values (coalesce(nullif(trim(c.client_name), ''), 'عميل'), 'استشارة أونلاين', c.rating, c.rating_text, true, c.provider_id, c.id)
  on conflict (consultation_id) where consultation_id is not null do nothing;
  return 'ok';
end; $$;
revoke all on function public.admin_approve_rating(uuid) from public, anon;
grant execute on function public.admin_approve_rating(uuid) to authenticated;

-- ratings approved before this file existed
insert into public.reviews (client_name, service_type, rating, text, is_approved, provider_id, consultation_id)
select coalesce(nullif(trim(c.client_name), ''), 'عميل'), 'استشارة أونلاين', c.rating, c.rating_text, true, c.provider_id, c.id
from public.consultations c where c.rating_ok and c.rating is not null
on conflict (consultation_id) where consultation_id is not null do nothing;

drop function if exists public.admin_consultations();
create or replace function public.admin_consultations()
 returns table (id uuid, case_number text, client_name text, client_phone text, provider_name text, provider_specialty text,
                channel text, price numeric, duration_min int, period_date date, period text, pay_method text, pay_status text,
                cancel_reason text, pay_deadline timestamptz, paid_at timestamptz, prop_at timestamptz, prop_status text,
                appt_at timestamptz, state text, started_at timestamptz, ended_at timestamptz, no_show boolean, refunded boolean,
                rating int, rating_text text, rating_ok boolean, created_at timestamptz, alerts text[], admin_contacted_at timestamptz,
                sum_note text, sum_recs text, sum_follow text, sum_at timestamptz)
 language sql stable security definer set search_path to 'public'
as $$
  select c.id, c.case_number, c.client_name, cl.phone, p.name, p.specialty,
         c.channel, c.price, c.duration_min, c.period_date, c.period, c.pay_method, c.pay_status,
         c.cancel_reason, c.pay_deadline, c.paid_at, c.prop_at, c.prop_status,
         c.appt_at, c.state, c.started_at, c.ended_at, c.no_show, c.refunded,
         c.rating, c.rating_text, c.rating_ok, c.created_at,
         array_remove(array[
           case when c.pay_status = 'pending' and c.pay_deadline < now() then 'deadline' end,
           case when c.pay_status = 'paid' and c.prop_status = 'none' and c.paid_at < now() - interval '30 minutes' then 'no_proposal' end,
           case when c.prop_status = 'pending' and c.updated_at < now() - interval '30 minutes' then 'client_silent' end,
           case when c.prop_status = 'no' then 'client_rejected' end,
           case when c.state = 'wait' and c.prop_status = 'ok' and c.appt_at + interval '15 minutes' < now() and c.admin_contacted_at is null then 'doctor_late' end,
           case when c.rating is not null and not c.rating_ok then 'rating' end,
           case when c.no_show and not c.refunded then 'no_show' end
         ], null),
         c.admin_contacted_at, c.sum_note, c.sum_recs, c.sum_follow, c.sum_at
  from public.consultations c
  join public.clients cl on cl.id = c.client_id
  join public.providers p on p.id = c.provider_id
  where public.is_admin()
  order by c.created_at desc
  limit 300;
$$;
revoke all on function public.admin_consultations() from public, anon;
grant execute on function public.admin_consultations() to authenticated;

-- ======== from 28_unpublish_rating.sql ========
