-- ======== from 32_install_attribution.sql ========
-- Test project only. Install-source tracking (where each user came from: facebook / tiktok / google / whatsapp ...).
-- The app reads the Google Play install referrer (utm_source=...&utm_medium=...&utm_campaign=...) on first launch (Android)
-- and sends it here once a user is signed in. One row per user; the first one wins.
create table if not exists public.install_attribution (
  user_id uuid primary key references auth.users(id) on delete cascade,
  referrer text,
  source text not null default 'unknown',
  medium text,
  campaign text,
  content text,
  platform text,
  created_at timestamptz not null default now()
);
alter table public.install_attribution enable row level security;
-- no policies: users never read or write it directly; they go through the functions below

create or replace function public.record_install_attribution(p_referrer text, p_platform text default null)
 returns text language plpgsql security definer set search_path to 'public'
as $$
declare
  uid uuid := auth.uid();
  q text := coalesce(btrim(p_referrer), '');
  src text; med text; cmp text; cnt text;
begin
  if uid is null then return 'unauthorized'; end if;
  if exists (select 1 from public.install_attribution where user_id = uid) then return 'exists'; end if;
  -- the referrer arrives as "utm_source=facebook&utm_medium=cpc&utm_campaign=oct_ads" (may be url-encoded)
  q := replace(q, '%3D', '='); q := replace(q, '%26', '&');
  src := lower(nullif(substring(q from '(?:^|&)utm_source=([^&]*)'), ''));
  med := lower(nullif(substring(q from '(?:^|&)utm_medium=([^&]*)'), ''));
  cmp := nullif(substring(q from '(?:^|&)utm_campaign=([^&]*)'), '');
  cnt := nullif(substring(q from '(?:^|&)utm_content=([^&]*)'), '');
  if src is null then src := case when q = '' then 'unknown' else 'other' end; end if;
  if src in ('ig', 'instagram.com') then src := 'instagram'; end if;
  if src in ('fb', 'facebook.com', 'apps.facebook.com', 'meta') then src := 'facebook'; end if;
  insert into public.install_attribution (user_id, referrer, source, medium, campaign, content, platform)
  values (uid, left(nullif(q, ''), 500), left(src, 60), left(med, 60), left(cmp, 100), left(cnt, 100), left(p_platform, 20))
  on conflict (user_id) do nothing;
  return 'ok';
end; $$;
revoke all on function public.record_install_attribution(text, text) from public, anon;
grant execute on function public.record_install_attribution(text, text) to authenticated;

-- Admin report: per source / medium / campaign — users, how many made a booking, how many paid a consultation
create or replace function public.admin_install_stats(p_days int default 30)
 returns table(source text, medium text, campaign text, users bigint, with_booking bigint, with_paid_consult bigint)
 language plpgsql security definer set search_path to 'public'
as $$
begin
  if not public.is_admin() then raise exception 'forbidden'; end if;
  return query
  select a.source, a.medium, a.campaign,
         count(*)::bigint,
         count(*) filter (where exists (select 1 from public.bookings b join public.clients c on c.id = b.client_id
                                         where c.auth_id = a.user_id and coalesce(b.status, '') <> 'cancelled'))::bigint,
         count(*) filter (where exists (select 1 from public.consultations k join public.clients c on c.id = k.client_id
                                         where c.auth_id = a.user_id and k.pay_status = 'paid'))::bigint
  from public.install_attribution a
  where a.created_at >= now() - make_interval(days => greatest(p_days, 1))
  group by a.source, a.medium, a.campaign
  order by count(*) desc;
end; $$;
revoke all on function public.admin_install_stats(int) from public, anon;
grant execute on function public.admin_install_stats(int) to authenticated;

-- ======== from 33_delete_my_account.sql ========
-- Test project only. In-app account deletion (required by Apple App Store and Google Play).
-- delete_my_account() is called by the signed-in user from the app. It:
--   * refuses while the user still has live work (open consultations / pending or confirmed bookings) -> 'active_items'
--   * removes the personal data and the login, keeps only anonymous business records (prices, dates, payment status)
--     so the other party's history and the accounting stay intact.
-- Returns 'ok' | 'active_items' | 'admin' | 'unauthorized'.
-- Needs 31_provider_name_en.sql (providers.name_en) to be applied first.

create or replace function public.delete_my_account()
 returns text language plpgsql security definer set search_path to 'public'
as $$
declare
  uid uuid := auth.uid();
  cid uuid; cphone text;
  pid uuid;
begin
  if uid is null then return 'unauthorized'; end if;
  if exists (select 1 from public.admin_users where user_id = uid) then return 'admin'; end if;

  select id, phone into cid, cphone from public.clients where auth_id = uid limit 1;
  select id into pid from public.providers where user_id = uid limit 1;

  -- live work blocks deletion (cancel / finish it first)
  if cid is not null and (
       exists (select 1 from public.consultations where client_id = cid and state in ('wait', 'live') and coalesce(pay_status, '') in ('paid', 'pending'))
    or exists (select 1 from public.bookings where client_id = cid and status in ('pending', 'confirmed'))) then
    return 'active_items';
  end if;
  if pid is not null and (
       exists (select 1 from public.consultations where provider_id = pid and state in ('wait', 'live') and coalesce(pay_status, '') in ('paid', 'pending'))
    or exists (select 1 from public.bookings where provider_id = pid and status in ('pending', 'confirmed'))) then
    return 'active_items';
  end if;

  if cid is not null then
    -- stored files (chat attachments, ask-a-doctor attachments, medical files)
    delete from storage.objects where bucket_id = 'consultation-files'
      and name in (select m.file_path from public.consultation_messages m join public.consultations c on c.id = m.consultation_id where c.client_id = cid and m.file_path is not null);
    delete from storage.objects where bucket_id = 'ask-doctor-attachments'
      and name in (select a.storage_path from public.ask_doctor_attachments a join public.ask_doctor_cases k on k.id = a.case_id where k.client_id = cid);
    delete from storage.objects where bucket_id = 'medical-files'
      and name in (select storage_path from public.medical_files where client_id = cid);
    -- chat content and ask-a-doctor content
    delete from public.consultation_messages where consultation_id in (select id from public.consultations where client_id = cid);
    delete from public.ask_doctor_attachments where case_id in (select id from public.ask_doctor_cases where client_id = cid);
    delete from public.ask_doctor_messages where case_id in (select id from public.ask_doctor_cases where client_id = cid);
    update public.ask_doctor_cases set patient_name = null, patient_phone = null, location = null,
           message = '[تم حذف المحتوى بناءً على طلب صاحب الحساب]' where client_id = cid;
    -- the client's personal records
    delete from public.medical_files where client_id = cid;
    delete from public.medicine_reminders where client_id = cid;
    delete from public.family_members where client_id = cid;
    delete from public.client_addresses where client_id = cid;
    delete from public.care_reports where patient_user_id = uid;
    delete from public.push_tokens where owner_type = 'client' and phone = cphone;
    -- business records stay, but anonymous
    update public.bookings set patient_name = 'حساب محذوف', phone = null, address = null, notes = null, patient_email = null, lat = null, lng = null where client_id = cid;
    update public.consultations set client_name = 'حساب محذوف' where client_id = cid;
    -- the client row is kept only as an anonymous anchor for those records (foreign keys), detached from the login
    update public.clients set auth_id = null, name = 'حساب محذوف', email = null, phone = 'deleted-' || id::text, phone2 = null,
           whatsapp = null, avatar_url = null, birth_date = null, gender = null where id = cid;
  end if;

  if pid is not null then
    delete from public.push_tokens where provider_id = pid;
    delete from public.provider_channels where provider_id = pid;
    delete from public.provider_services where provider_id = pid;
    delete from public.testimonials where provider_id = pid;
    delete from public.booking_offers where provider_id = pid;
    update public.bookings set provider_phone = null where provider_id = pid;
    update public.providers set user_id = null, status = 'suspended', is_available = false, name = 'مقدم خدمة سابق', name_en = null,
           email = null, phone = null, whatsapp = null, bio = null, photo_url = null, lat = null, lng = null where id = pid;
  end if;

  -- finally the login itself (cascades to sessions, identities, aac_* and install_attribution)
  delete from auth.users where id = uid;
  return 'ok';
end; $$;
revoke all on function public.delete_my_account() from public, anon;
grant execute on function public.delete_my_account() to authenticated;

